load_model_preset() {
  case $1 in
    1)
      PRESET_MODEL='gpt-6-sol'
      PRESET_REASONING_EFFORT='medium'
      PRESET_CONTEXT_WINDOW='272000'
      ;;
    2)
      PRESET_MODEL='gpt-6-astra'
      PRESET_REASONING_EFFORT='low'
      PRESET_CONTEXT_WINDOW='272000'
      ;;
    3)
      PRESET_MODEL='gpt-6-luna'
      PRESET_REASONING_EFFORT='medium'
      PRESET_CONTEXT_WINDOW='272000'
      ;;
    4)
      PRESET_MODEL='gpt-5.6-sol'
      PRESET_REASONING_EFFORT='medium'
      PRESET_CONTEXT_WINDOW='272000'
      ;;
    *) return 1 ;;
  esac
}
